function d_backup_verify(P,R){function h(s){var x=0;for(var i=0;i<s.length;i++)x=(Math.imul(x,31)+s.charCodeAt(i))|0;return(x>>>0).toString(16);}var n=P.blocks||8,chain=[],prev='0';for(var i=0;i<n;i++){var cur=h(prev+':block'+i);chain.push({block:i,hash:cur});prev=cur;}var ok=true,ph='0';chain.forEach(function(b,i){if(h(ph+':block'+i)!==b.hash)ok=false;ph=b.hash;});return{blocks:n,chain_head:prev,integrity_ok:ok,restorable:ok};}

